"use strict";(globalThis.webpackChunkgrc||=[]).push([[28578],{57318(e){e.exports=JSON.parse('{"citeKey":"jin2009performancefailures","slug":"jin-2009-performance-failures-c6e7","title":"Performance under Failures of DAG-based Parallel Computing","authors":["H. Jin","X.-H. Sun","Z. Zheng","Z. Lan","B. Xie"],"venue":"The IEEE/ACM International Symposium on Cluster Computing and the Grid (CCGrid\'09), Shanghai, China","type":"Conference","entryType":"inproceedings","date":"May, 2009","year":2009,"era":"iit","month":5,"doi":"10.1109/ccgrid.2009.55","abstract":"As the scale and complexity of parallel systems continue to grow, failures become more and more an inevitable fact for solving large-scale applications. In this research, we present an analytical study to estimate execution time in the presence of failures of directed acyclic graph (DAG) based Scientific Applications and provide a guideline for performance optimization. The study is four fold. We first introduce a performance model to predict individual subtask computation time under failures. Next, a layered, iterative approach is adopted to transform a DAG into a layered DAG, which reflects full dependencies among all the subtasks. Then, the expected execution time under failures of the DAG is derived based on stochastic analysis. Unlike existing models, this newly proposed performance model provides both the variance and distribution. It is practical and can be put to real use. Finally, based on the model, performance optimization, weak point identification and enhancement are proposed. Intensive simulations are conducted to verify the analytical findings. They show that the newly proposed model and weak point enhancement mechanism work well.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2009/jin-2009-performance-failures-c6e7.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);